def classify_substance(pH):
    if pH < 7:
        return "Acid"
    elif pH > 7:
        return "Base"
    else:
        return "Neutral"

# Example usage:
print(classify_substance(3))  # Output: Acid
print(classify_substance(10)) # Output: Base
print(classify_substance(7))  # Output: Neutral

def is_prime(n):
    if n <= 1:
        return False
    for i in range(2, int(n**0.5) + 1):
        if n % i == 0:
            return False
    return True

# Example usage
number = 29
print(is_prime(number))  # Output: True

#include <iostream>
using namespace std;

int main() {
    int num1, num2, sum;
    cout << "Enter two numbers: ";
    cin >> num1 >> num2; // Input two numbers
    sum = num1 + num2;   // Add the numbers
    cout << "Sum: " << sum << endl; // Output the sum
    return 0;
}

def factorial(n):
    if n == 0:
        return 1
    else:
        return n * factorial(n - 1)

# Example usage
print(factorial(5))  # Output: 120

#include <iostream>
using namespace std;

class Car {
public:
    string brand;
    int year;

    void displayInfo() {
        cout << "Brand: " << brand << ", Year: " << year << endl;
    }
};

int main() {
    Car myCar;
    myCar.brand = "Toyota";
    myCar.year = 2020;
    myCar.displayInfo();
    return 0;
}
